-- =============================================================================
--  Demo dataset (optional) - a small fictional landscape survey
-- -----------------------------------------------------------------------------
--  Adds example attribute fields (incl. a 3-level hierarchy) and ~20 features
--  around Kutna Hora (CZ) so you can try the app right away. Names and
--  attributes are illustrative only. Load it with:
--
--      php tools/install.php --demo        (after or together with the normal install)
--
--  Also creates the user `demo.collector` as a second author. That account
--  CANNOT log in (its password hash is invalid) - an admin can reset it in the app.
--  Do not load this into a production database.
-- =============================================================================

SET NAMES utf8mb4;

INSERT IGNORE INTO users (username, email, password_hash, display_name, role, is_active)
VALUES ('demo.collector', NULL, '!', 'Demo Collector', 'collector', 1);

INSERT IGNORE INTO field_definitions
    (field_key, label, help_text, data_type, options, is_required, validation, applies_to, default_value, sort_order, is_active)
VALUES
    ('classification', 'Classification', 'Pick the group, type and variant of the feature.', 'hierarchy', '[{"value": "settlement", "label": "Settlement", "children": [{"value": "residential", "label": "Residential", "children": [{"value": "farmstead", "label": "Farmstead"}, {"value": "manor", "label": "Manor house"}, {"value": "cottage", "label": "Cottage"}]}, {"value": "public", "label": "Public building", "children": [{"value": "inn", "label": "Inn"}, {"value": "school", "label": "School"}]}]}, {"value": "religious", "label": "Religious site", "children": [{"value": "sacral", "label": "Sacral building", "children": [{"value": "church", "label": "Church"}, {"value": "chapel", "label": "Chapel"}]}, {"value": "small", "label": "Small monument", "children": [{"value": "wayside_cross", "label": "Wayside cross"}, {"value": "shrine", "label": "Shrine"}]}]}, {"value": "production", "label": "Production", "children": [{"value": "water_power", "label": "Water power", "children": [{"value": "watermill", "label": "Watermill"}, {"value": "sawmill", "label": "Sawmill"}]}, {"value": "extraction", "label": "Extraction", "children": [{"value": "quarry", "label": "Quarry"}, {"value": "mine_shaft", "label": "Mine shaft"}, {"value": "spoil_heap", "label": "Spoil heap"}]}]}, {"value": "landscape", "label": "Landscape", "children": [{"value": "water", "label": "Water management", "children": [{"value": "pond", "label": "Fishpond"}, {"value": "millrace", "label": "Millrace"}]}, {"value": "agrarian", "label": "Agrarian", "children": [{"value": "field_boundary", "label": "Field boundary"}, {"value": "orchard", "label": "Orchard"}]}, {"value": "transport", "label": "Transport", "children": [{"value": "historic_road", "label": "Historic road"}, {"value": "hollow_way", "label": "Hollow way"}]}]}]', 1, '{"levels": [{"key": "class_group", "label": "Group"}, {"key": "class_type", "label": "Type"}, {"key": "class_variant", "label": "Variant"}]}', NULL, NULL, 10, 1),
    ('period', 'Period', NULL, 'select', '[{"value": "medieval", "label": "Medieval"}, {"value": "early_modern", "label": "Early modern (1500–1800)"}, {"value": "c19", "label": "19th century"}, {"value": "c20", "label": "20th century"}, {"value": "unknown", "label": "Unknown"}]', 0, NULL, NULL, NULL, 20, 1),
    ('condition', 'State of preservation', NULL, 'select', '[{"value": "preserved", "label": "Preserved"}, {"value": "altered", "label": "Altered"}, {"value": "ruin", "label": "Ruin"}, {"value": "vanished", "label": "Vanished – no visible remains"}]', 0, NULL, NULL, NULL, 30, 1),
    ('dating', 'Dating', 'Free text, e.g. "1st half of the 17th c." or a year range.', 'text', NULL, 0, '{"maxLength": 120}', NULL, NULL, 40, 1),
    ('first_mapped', 'First mapped', 'Year of the earliest map showing the feature.', 'integer', NULL, 0, '{"min": 1500, "max": 2100}', NULL, NULL, 50, 1),
    ('field_verified', 'Verified in the field', NULL, 'boolean', NULL, 0, NULL, NULL, 'false', 60, 1),
    ('notes', 'Notes', NULL, 'textarea', NULL, 0, '{"maxLength": 4000}', NULL, NULL, 70, 1),
    ('source', 'Source', 'Literature, archival source, historical map …', 'textarea', NULL, 0, '{"maxLength": 2000}', NULL, NULL, 80, 1),
    ('photos', 'Photos', NULL, 'photos', NULL, 0, NULL, NULL, NULL, 90, 1);

SET @admin = (SELECT id FROM users WHERE role = 'admin' AND is_active = 1 ORDER BY id LIMIT 1);
SET @collector = (SELECT id FROM users WHERE username = 'demo.collector');

-- Skip the features when the demo was loaded before (avoids duplicates).
SET @already = (SELECT COUNT(*) FROM features WHERE created_by = @collector);

